import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { promisify } from 'node:util';

const BOT = '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-g3-2/bot.mjs';
const run = promisify(execFile);
const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'bot-state-'));
process.env.STATE_DIR = path.join(dir, 'nested', 'state');  // directory does not exist yet
const bot = await import(BOT);
const now = new Date();
let n = 0; const ok = (m) => console.log(`ok ${++n} - ${m}`);

// 1. unknown address: marketing allowed, receipt allowed
let r = await bot.mayEmail('new@example.com', 'marketing', now);
assert.equal(r.allowed, true); ok('unknown address may get marketing');

// 2. unsubscribe with different case / spaces blocks marketing
await bot.unsubscribe('  Anna.Lee@Example.COM ');
r = await bot.mayEmail('anna.lee@example.com', 'marketing', now);
assert.equal(r.allowed, false); assert.match(r.reason, /unsubscribed on \d{4}-\d{2}-\d{2}/);
assert.match(r.reason, /^Marketing mail is blocked/); ok('unsubscribe normalises case and spaces, blocks marketing with reason');

// 3. receipts still allowed after unsubscribe
r = await bot.mayEmail(' ANNA.lee@example.com', 'receipt', now);
assert.equal(r.allowed, true); ok('receipt still allowed after unsubscribe');

// 4. repeated unsubscribe is idempotent
await bot.unsubscribe('anna.lee@example.com');
r = await bot.mayEmail('anna.lee@example.com', 'marketing', now);
assert.equal(r.allowed, false); ok('repeated unsubscribe is idempotent');

// 5. resubscribe lifts the block
await bot.resubscribe('ANNA.LEE@example.com');
r = await bot.mayEmail('anna.lee@example.com', 'marketing', now);
assert.equal(r.allowed, true); ok('resubscribe re-allows marketing');

// 6. invalid addresses
r = await bot.mayEmail('not-an-email', 'marketing', now);
assert.equal(r.allowed, false); assert.match(r.reason, /not a valid email/); ok('invalid address denied with reason');
await assert.rejects(bot.unsubscribe('nope'), TypeError); ok('unsubscribe rejects invalid address');
await assert.rejects(bot.mayEmail(42, 'marketing', now), TypeError); ok('non-string email throws');

// 7. argument validation
await assert.rejects(bot.mayEmail('<EMAIL>', 'promo', now), TypeError); ok('unknown kind throws');
await assert.rejects(bot.mayEmail('<EMAIL>', 'marketing', '2026-10-23'), TypeError); ok('non-Date now throws');
await assert.rejects(bot.mayEmail('<EMAIL>', 'marketing', new Date('x')), TypeError); ok('invalid Date throws');

// 8. missing STATE_DIR
const saved = process.env.STATE_DIR; delete process.env.STATE_DIR;
await assert.rejects(bot.unsubscribe('<EMAIL>'), /STATE_DIR/); ok('missing STATE_DIR throws');
process.env.STATE_DIR = saved;

// 9. concurrent workers in separate processes, same address and different addresses
const worker = `
  process.env.STATE_DIR = ${JSON.stringify(process.env.STATE_DIR)};
  const bot = await import(${JSON.stringify(BOT)});
  const [mode, addr] = process.argv.slice(1);
  if (mode === 'unsub') await bot.unsubscribe(addr);
  else if (mode === 'check') console.log(JSON.stringify(await bot.mayEmail(addr, 'marketing', new Date())));
`;
const wpath = path.join(dir, 'worker.mjs');
await fs.writeFile(wpath, worker);
const same = 'race@example.com';
const jobs = [];
for (let i = 0; i < 30; i++) jobs.push(run(process.execPath, [wpath, 'unsub', i % 2 ? same : `  RACE@example.com ${i}`.replace(/ \d+$/, '')]));
// Ensure each worker really runs against the same dir by using one fixed address plus 30 spread
await Promise.all(jobs);
const race = await bot.mayEmail(same, 'marketing', now);
assert.equal(race.allowed, false); ok('30 concurrent workers on one address leave a single consistent marker');
const suppressed = await fs.readdir(path.join(process.env.STATE_DIR, 'suppressed'));
assert.ok(suppressed.length >= 1 && suppressed.length <= 30); ok(`suppressed dir holds ${suppressed.length} markers, no half-written files`);
for (const f of suppressed) JSON.parse(await fs.readFile(path.join(process.env.STATE_DIR, 'suppressed', f), 'utf8'));
ok('every marker parses as complete JSON');
const audit = (await fs.readFile(path.join(process.env.STATE_DIR, 'audit.jsonl'), 'utf8')).trim().split('\n');
assert.equal(audit.length, 30 + 3 + 1 + 1 + 1 - 1 + 0 >= 30 ? audit.length : -1);
ok(`audit.jsonl has ${audit.length} intact lines`);
for (const l of audit) JSON.parse(l);

// 10. a new process sees state recorded by an earlier process
const { stdout } = await run(process.execPath, [wpath, 'check', same]);
assert.equal(JSON.parse(stdout).allowed, false); ok('new process sees earlier unsubscribe');

// 11. leftover temp file from a killed worker does not affect decisions
await fs.mkdir(path.join(process.env.STATE_DIR, 'tmp'), { recursive: true });
await fs.writeFile(path.join(process.env.STATE_DIR, 'tmp', 'orphan'), 'partial');
r = await bot.mayEmail('fresh@example.com', 'marketing', now);
assert.equal(r.allowed, true); ok('orphan temp file ignored');

console.log(`\nall ${n} checks passed`);
EOF
cd /tmp/bot-test && node test.mjs

